<script setup lang="ts">
import type {ForumPost} from '~/types/forum'
import type {MemberProfile} from '~/types/community'
const route=useRoute(),api=useRequestFetch(),tab=ref('posts'),page=ref(1)
const userId=computed(()=>String(route.params.id))
const {data:profile,error}=await useAsyncData(()=>`member:${userId.value}`,()=>api<MemberProfile>('/api/users/'+encodeURIComponent(userId.value)))
const {data:posts}=await useAsyncData(()=>`member-posts:${userId.value}:${page.value}`,()=>api<{items:ForumPost[],total:number}>(`/api/users/${encodeURIComponent(userId.value)}/posts?page=${page.value}`))
const {data:replies}=await useAsyncData(()=>`member-replies:${userId.value}:${page.value}`,()=>api<{items:{id:string,postId:string,title:string,content:string}[],total:number}>(`/api/users/${encodeURIComponent(userId.value)}/replies?page=${page.value}`))
const states={wish:'想读',reading:'在读',finished:'已读'}
watch(tab,()=>page.value=1)
useSeoMeta({title:()=>`${profile.value?.nickname||'用户主页'} · 澄之响`,description:()=>profile.value?.signature||'看看这位同好的故事与公开书单。'})
</script>
<template><div v-if="profile" class="experience-page"><header class="member-hero"><UserAvatar :src="profile.avatarUrl" :name="profile.nickname" size="5rem" /><div><p class="eyebrow">A READER, A STORY</p><h1>{{ profile.nickname }}</h1><p class="member-signature">{{ profile.signature||'故事之外，期待与你相遇。' }}</p><small>{{ profile.stats.posts }} 篇帖子 · {{ profile.stats.replies }} 条回复 · {{ new Date(Number(profile.createdAt)).toLocaleDateString('zh-CN') }} 加入</small></div></header><nav class="experience-tabs" aria-label="用户主页内容"><button v-for="item in [{id:'posts',name:'发表的帖子'},{id:'replies',name:'最近回复'},{id:'library',name:'公开书单'}]" :key="item.id" :aria-pressed="tab===item.id" @click="tab=item.id">{{ item.name }}</button></nav><section v-if="tab==='posts'"><PostCard v-for="post in posts?.items" :key="post.id" :post="post" /><p v-if="!posts?.items.length" class="empty-state">还没有公开的帖子。</p></section><section v-if="tab==='replies'"><article v-for="item in replies?.items" :key="item.id" class="public-reply"><NuxtLink :to="'/post/'+item.postId+'#reply-'+item.id">{{ item.title }}</NuxtLink><p>{{ item.content }}</p></article><p v-if="!replies?.items.length" class="empty-state">还没有公开回复。</p></section><section v-if="tab==='library'" class="member-library"><article v-for="item in profile.library" :key="item.workId" class="experience-card"><span class="small-kicker">{{ states[item.state] }}</span><h2><NuxtLink :to="'/works/'+item.workId">{{ item.work.title }}</NuxtLink></h2><p>{{ item.note||'暂未留下短评。' }}</p></article><p v-if="!profile.library.length" class="empty-state">这位同好暂未公开书单。</p></section><div v-if="tab!=='library'" class="page-controls"><button :disabled="page===1" @click="page--">上一页</button><span>{{ page }}</span><button :disabled="page*12>=(tab==='posts'?posts?.total||0:replies?.total||0)" @click="page++">下一页</button></div></div><div v-else class="empty-state"><h1>暂时无法打开这个用户主页</h1><p>{{ error?'用户可能已停用、注销，或服务暂不可用。':'' }}</p><NuxtLink to="/">回到社区</NuxtLink></div></template>
